compile.workshop:
variables {
    global:
        0: g
}

rule ("r") {
    event {
        Ongoing - Global;
    }
    actions {
        Skip If(Compare(Global.g, ==, 1), 1);
        Set Global Variable(g, 5);
        Abort If(Compare(Global.g, ==, 2));
        Set Global Variable(g, 6);
        Loop If(Compare(Global.g, ==, 3));
    }
}

